fn task_status_to_str(status: TaskStatus) -> &'static str {
    match status {
        TaskStatus::Queued => "queued",
        TaskStatus::Running => "running",
        TaskStatus::Completed => "completed",
        TaskStatus::Failed => "failed",
    }
}

fn task_status_from_str(s: &str) -> TaskStatus {
    match s {
        "queued" => TaskStatus::Queued,
        "running" => TaskStatus::Running,
        "completed" => TaskStatus::Completed,
        "failed" => TaskStatus::Failed,
        _ => TaskStatus::Queued,
    }
}

fn event_type_to_str(status: EventType) -> &'static str {
    match status {
        EventType::TaskCreated => "task_created",
        EventType::TaskStarted => "task_started",
        EventType::TaskCompleted => "task_completed",
        EventType::TaskFailed => "task_failed",
        EventType::MessageSent => "message_sent",
        EventType::MessageReceived => "message_received",
    }
}

fn event_type_from_str(s: &str) -> EventType {
    match s {
        "task_created" => EventType::TaskCreated,
        "task_started" => EventType::TaskStarted,
        "task_completed" => EventType::TaskCompleted,
        "task_failed" => EventType::TaskFailed,
        "message_sent" => EventType::MessageSent,
        "message_received" => EventType::MessageReceived,
        _ => EventType::TaskCreated,
    }
}

